command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="24bb8722c06b302f6a6b9c00aad34293a38be0d0";$candidate="42453d5a3a914eb01b16cc5b28fb1f72e059014a";$branch="work/unc-network-copy-move-20261007"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "UNC Release fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before UNC Release"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "UNC Release candidate moved"}
$temp=Join-Path $env:RUNNER_TEMP ("fly-unc-release-"+$env:GITHUB_RUN_ID)
if(Test-Path $temp){Remove-Item $temp -Recurse -Force}
try{
 & git worktree add --detach $temp $candidate
 if($LASTEXITCODE -ne 0){throw "UNC Release worktree add failed"}
 Set-Location $temp
 & git diff --check ($main+"..."+$candidate)
 if($LASTEXITCODE -ne 0){throw "UNC Release diff check failed"}
 & .\tests\winui\m22\build.cmd Release
 if($LASTEXITCODE -ne 0){throw "UNC M22 Release build failed"}
 $env:FLY_M22_CONFIG="Release";$env:FLY_M22_LOOPBACK_ADMIN_SHARE="YES"
 & python -X utf8 .\tests\winui\m22\test_native.py
 if($LASTEXITCODE -ne 0){throw "UNC M22 Release native failed"}
 Remove-Item Env:FLY_M22_CONFIG -ErrorAction SilentlyContinue
 Remove-Item Env:FLY_M22_LOOPBACK_ADMIN_SHARE -ErrorAction SilentlyContinue
 & .\build.bat Release
 if($LASTEXITCODE -ne 0){throw "UNC canonical Release build failed"}
 & python -X utf8 tools\winui\run_checks.py gui --area file-operations --configuration Release
 if($LASTEXITCODE -ne 0){throw "UNC focused file-operations GUI failed"}
 Write-Host "UNC_COPY_MOVE_M22_RELEASE=PASS"
 Write-Host "UNC_COPY_MOVE_RELEASE_BUILD=PASS"
 Write-Host "UNC_COPY_MOVE_LOCAL_ISOLATED_GUI=PASS"
 Write-Host "UNC_COPY_MOVE_PHYSICAL_SMB=NOT_RUN_NO_OWNED_SHARE"
}finally{
 Remove-Item Env:FLY_M22_CONFIG -ErrorAction SilentlyContinue
 Remove-Item Env:FLY_M22_LOOPBACK_ADMIN_SHARE -ErrorAction SilentlyContinue
 Set-Location $repo
 if(Test-Path $temp){& git worktree remove --force $temp}
 & git worktree prune
}
